129	import org.jboss.resteasy.reactive.NoCache;
130	
131	import static org.keycloak.util.JsonSerialization.readValue;
132	
133	/**
134	 * Base resource class for the admin REST api of one realm
135	 *
136	 * @resource Realms Admin
137	 * @author <a href="mailto:bill@burkecentral.com">Bill Burke</a>
138	 * @version $Revision: 1 $
139	 */
140	@Extension(name = KeycloakOpenAPI.Profiles.ADMIN, value = "")
141	public class RealmAdminResource {
142	    protected static final Logger logger = Logger.getLogger(RealmAdminResource.class);
143	
144	    protected final AdminPermissionEvaluator auth;
145	    protected final RealmModel realm;
146	    private final AdminEventBuilder adminEvent;
147	
148	    protected final KeycloakSession session;
149	
150	    protected final ClientConnection connection;
151	
152	    protected final HttpHeaders headers;
153	
154	    public RealmAdminResource(KeycloakSession session, AdminPermissionEvaluator auth, AdminEventBuilder adminEvent) {
155	        this.session = session;
156	        this.auth = auth;
157	        this.realm = session.getContext().getRealm();
158	        this.connection = session.getContext().getConnection();
159	        this.adminEvent = adminEvent.resource(ResourceType.REALM);
160	        this.headers = session.getContext().getRequestHeaders();
161	    }
162	
163	    /**
164	     * Base path for importing clients under this realm.
165	     *
166	     * @return
167	     */
168	    @Path("client-description-converter")
169	    @Consumes({ MediaType.APPLICATION_JSON, MediaType.APPLICATION_XML, MediaType.TEXT_PLAIN })
170	    @POST
171	    @Produces(MediaType.APPLICATION_JSON)
172	    @Tag(name = KeycloakOpenAPI.Admin.Tags.REALMS_ADMIN)
173	    @Operation(summary = "Base path for importing clients under this realm.")
174	    @APIResponses(value = {
175	        @APIResponse(responseCode = "200", description = "OK", content = @Content(schema = @Schema(implementation = ClientRepresentation.class))),
176	        @APIResponse(responseCode = "403", description = "Forbidden"),
177	        @APIResponse(responseCode = "404", description = "Not Found")
178	    })
179	    public ClientRepresentation convertClientDescription(String description) {
180	        auth.clients().requireManage();
181	
182	        if (realm == null) {
183	            throw new NotFoundException("Realm not found.");
184	        }
185	
186	        return session.getKeycloakSessionFactory().getProviderFactoriesStream(ClientDescriptionConverter.class)
187	                .map(ClientDescriptionConverterFactory.class::cast)
188	                .filter(factory -> factory.isSupported(description))
189	                .map(factory -> factory.create(session).convertToInternal(description))
190	                .findFirst()
191	                .orElseThrow(() -> new BadRequestException("Unsupported format"));
192	    }
193	
194	    /**
195	     * Base path for managing attack detection.
196	     *
197	     * @return
198	     */
199	    @Path("attack-detection")
200	    public AttackDetectionResource getAttackDetection() {
201	        return new AttackDetectionResource(session, auth, adminEvent);
202	    }
203	
204	    /**
205	     * Base path for managing clients under this realm.
206	     *
207	     * @return
