    if (!Constants.GENERATE.equals(rep.getPublicKey()) && (rep.getPrivateKey() != null && rep.getPublicKey() != null)) {
        try {
            KeyPairVerifier.verify(rep.getPrivateKey(), rep.getPublicKey());
